import React from 'react';

import Trophy from '@pohodnik/icons/svg/RealWorld/Trophy';
import Plus from '@pohodnik/icons/svg/Signs/Plus';
import { useNavigate } from 'react-router-dom';

import Page from '@components/Page';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import WorkoutsInviteCounter from '../components/WorkoutsInviteCounter';
import WorkoutsList from '../components/WorkoutsList';

interface IWorkoutsProps {
  search?: any;
}

const Workouts: React.FC<IWorkoutsProps> = ({ search }) => {
  const navigate = useNavigate();

  return (
    <Page title="Все тренировки">
      <Breadcrumb data={[{ href: `/workouts`, text: 'Все тренировки', active: true }]} />
      <PohContainer>
        <PohRow className="mb-2">
          <PohCol md={6} xs={6} className="d-flex align-items-baseline">
            <h3 className="mb-0">Все тренировки</h3>
            <WorkoutsInviteCounter before={<span className="ms-4">Приглашений:</span>} />
          </PohCol>
          <PohCol md={6} xs={6} className="text-end">
            <PohButton
              size={ButtonSize.Small}
              variant={ButtonVariant.Light}
              onClick={() => navigate(`/workouts/targets`)}
            >
              <Trophy />
              &nbsp; Цели<sup className="text-success">new</sup>
            </PohButton>
            &nbsp;
            <PohButton
              size={ButtonSize.Small}
              variant={ButtonVariant.Light}
              onClick={() =>
                navigate(
                  `/workouts/my?y=${new Date().getFullYear()},${new Date().getFullYear() - 1}`,
                )
              }
            >
              Мои тренировки
            </PohButton>
            &nbsp;
            <PohButton
              size={ButtonSize.Small}
              variant={ButtonVariant.Success}
              onClick={() => navigate('/workouts/new')}
            >
              <Plus />
              &nbsp;Добавить
            </PohButton>
          </PohCol>
        </PohRow>
        <PohRow>
          <PohCol sm={12}>
            <WorkoutsList batchSize={50} d1={search?.d1} d2={search?.d2} tag={search?.tag} />
          </PohCol>
        </PohRow>
      </PohContainer>
    </Page>
  );
};

export default Workouts;
